contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        // Read whether this contract holds the PAUSER_ROLE through the public getter
        bool hasRoleBefore = c.hasRole(PAUSER_ROLE, address(this));

        // Attempt to pause the protocol
        bool reverted;
        try c.pause() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: pause() is permissioned by PAUSER_ROLE —
        // it reverts exactly when the caller lacks the role.
        assert(reverted != hasRoleBefore);
    }
    receive() external payable {}
}

