contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token, uint256 amount, address to) public {
        DepositParams memory params = DepositParams({token: token, amount: amount, to: to});

        bool reverted;
        try c.deposit(params) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: on an uninitialized C, every deposit input combination
        // must revert — either because the token is neither of the (zero) configured
        // underlying tokens, or because operating on the zero-address tokens fails.
        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 role, address account) public {
        require(account != address(0));

        bool granted;
        try c.grantRole(role, account) {
            granted = true;
        } catch {
            granted = false;
        }

        bool hasAfter = c.hasRole(role, account);

        // General rule: grantRole(role, account) succeeds exactly when the account
        // ends up holding the role. Any success without effect, or silent failure,
        // would break this equivalence.
        assert(hasAfter == granted);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 cash, uint256 tenor) public {
        bool reverted;
        uint256 fee;

        // getSwapFee is a read-only call: safe to probe with try/catch
        try c.getSwapFee(cash, tenor) returns (uint256 f) {
            reverted = false;
            fee = f;
        } catch {
            reverted = true;
        }

        // General rule: the zero tenor is rejected, and any valid query on an
        // uninitialized protocol (swapFeeAPR == 0) must yield a zero swap fee,
        // never a nonzero one, for every cash amount.
        assert((reverted == (tenor == 0)) && (!reverted || fee == 0));
    }
}

