    }

    function run(uint256 id) public {
        uint256 debtCount;
        uint256 creditCount;
        (debtCount, creditCount) = c.getPositionsCount();

        bool isDebt = c.isDebtPositionId(id);
        bool isCredit = c.isCreditPositionId(id);

        assert(
            isDebt == (id < debtCount)
                && isCredit == (id >= type(uint256).max / 2 && id < creditCount)
        );
    }
}

