contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address user) public payable {
        require(true);
        // Fresh deployment: `user` has never deposited or borrowed, so debt is 0.
        // The rule: collateralRatio must be type(uint256).max whenever debt is zero,
        // and never revert for any address.
        uint256 cr = c.collateralRatio(user);
        bool underwater = c.isUserUnderwater(user);
        assert(cr == type(uint256).max && !underwater);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 cash, uint256 tenorSmall, uint256 tenorBig) public payable {
        require(cash > 0);
        require(tenorSmall > 0);
        require(tenorBig >= tenorSmall);

        uint256 feeSmall = c.getSwapFee(cash, tenorSmall);
        uint256 feeBig = c.getSwapFee(cash, tenorBig);

        // Rule: the swap fee grows at least as fast as the tenor, since the
        // fee percent is apr * tenor / YEAR with apr > 0, so for t1 <= t2 the
        // fee at t1 can never exceed the fee at t2 for the same cash amount.
        assert(feeSmall <= feeBig);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 aprLow, uint256 aprHigh) public payable {
        require(aprLow <= aprHigh);
        require(aprHigh < 1e18);

        InitializeRiskConfigParams memory rc = c.riskConfig();
        require(rc.minTenor > 0 && rc.maxTenor > rc.minTenor);

        // Place a valid loan limit order (multipliers zero so the APR comes purely from the curve)
        YieldCurve memory curve;
        curve.tenors = new uint256[](2);
        curve.tenors[0] = rc.minTenor;
        curve.tenors[1] = rc.maxTenor;
        curve.aprs = new int256[](2);
        curve.aprs[0] = int256(aprLow);
        curve.aprs[1] = int256(aprHigh);
        curve.marketRateMultipliers = new uint256[](2);
        curve.marketRateMultipliers[0] = 0;
        curve.marketRateMultipliers[1] = 0;

        BuyCreditLimitParams memory params = BuyCreditLimitParams({
            maxDueDate: block.timestamp + rc.maxTenor + 1 days,
            curveRelativeTime: curve
        });
        c.buyCreditLimit(params);

        bool okAfterSet = false;
        try c.getLoanOfferAPR(address(this), rc.maxTenor) returns (uint256 apr) {
            okAfterSet = (apr >= aprLow && apr <= aprHigh);
        } catch {
            okAfterSet = false;
        }

        // Clear the order with a null offer
        YieldCurve memory emptyCurve;
        emptyCurve.tenors = new uint256[](0);
        emptyCurve.aprs = new int256[](0);
        emptyCurve.marketRateMultipliers = new uint256[](0);
        c.buyCreditLimit(BuyCreditLimitParams({maxDueDate: 0, curveRelativeTime: emptyCurve}));

        bool revertedAfterClear;
        try c.getLoanOfferAPR(address(this), rc.maxTenor) {
            revertedAfterClear = false;
        } catch {
            revertedAfterClear = true;
        }

        assert(okAfterSet && revertedAfterClear);
    }

    receive() external payable {}
}

