contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 cash, uint256 tenor) public {
        require(cash > 0 && cash < 1e30);
        require(tenor > 0 && tenor < 1e7);
        InitializeFeeConfigParams memory f = c.feeConfig();
        require(f.swapFeeAPR > 0 && f.swapFeeAPR < 1e18);
        uint256 fee = c.getSwapFee(cash, tenor);
        uint256 expected = FixedPointMathLib.mulDivUp(
            cash, FixedPointMathLib.mulDivUp(f.swapFeeAPR, tenor, YEAR), PERCENT
        );
        assert(fee == expected);
    }
